        assertThat(initiateBox("alice", box, 2, "bob").getResponse().getStatus()).isEqualTo(200);

        // 待交接期间禁改成员
        assertThat(pack("alice", box, 2, List.of(e2), List.of()).getResponse().getStatus())
                .isEqualTo(409);
